import test from 'node:test';
import assert from 'node:assert/strict';
import { fixture } from './hundred-hand-mile-finite-fixture.mjs';
import { documentAdapter } from './hundred-hand-mile-dom-adapter.mjs';
import { createPromptDeck } from '../src/ui/promptDeck.js';
import { hundredHandMilePrompt } from '../src/ui/hundredHandMilePrompt.js';
import { hundredHandMileIntegration } from '../src/systems/hundredHandMileIntegration.js';
import { hundredHandMileTraffic, MILE_CONVOY_JOB, MILE_CONVOY_ROUTE } from '../src/systems/hundredHandMileTraffic.js';
import { spawnBudget } from '../src/systems/spawnBudget.js';
import { npcJobsRuntime } from '../src/systems/npcJobsRuntime.js';
import { HUNDRED_HAND_MILE as C, HUNDRED_HAND_POS as POS, validHundredHandSaveSection } from '../src/data/hundredHandMile.js';
import { freshIlexArk, ILEX_ARK, ILEX_VAULT_IDS } from '../src/data/ilexArk.js';
import { LAST_SHIFT, LAST_SHIFT_CLUES, freshLastShiftRecord, lastShiftReport } from '../src/data/lastShift.js';

// Explicit owner/DOM fixture, not native traversal or rendered gameplay acceptance.
// The existing finite fixture supplies earned prerequisite records and native ports;
// this adds the actual traffic owner with synthetic native poses and job phases.
function boot() {
  const h = fixture(), native = new Map(), doc = documentAdapter();
  h.state.mode = 'flight';
  const ctx = { state: h.state, bus: h.bus, helpers: h.helpers, registry: { get: id => h.owners.get(id) } };
  for (const [id, source] of [['spawnBudget', spawnBudget], ['npcJobsRuntime', npcJobsRuntime], ['hundredHandMileTraffic', hundredHandMileTraffic]]) {
    const owner = Object.create(source); h.owners.set(id, owner); owner.init(ctx);
  }
  const traffic = h.owners.get('hundredHandMileTraffic');
  const world = {
    ports: () => ({ ...h.ports, proveRoute: () => world.proveRoute() }),
    inspectSite: () => ({ ok: true, siteId: C.siteId, tick: h.state.tick }),
    proveRoute: () => ({ ok: true, routeId: C.routeId, tick: h.state.tick }),
    nativePosition: e => native.get(e) || null,
  };
  h.owners.set('hundredHandMileWorld', world);
  const integration = Object.create(hundredHandMileIntegration), prompt = Object.create(hundredHandMilePrompt);
  const deck = createPromptDeck({ document: doc, state: h.state, bus: h.bus });
  integration.init(ctx); prompt.init(ctx);
  const player = h.state.entities.get(h.state.playerId);
  native.set(player, { ...POS });
  const site = h.helpers.spawnEntity({ type: 'payload', pos: { ...POS }, data: { persistenceOwner: 'hundredHandMileWorld' } });
  assert.equal(h.graph.accept(h.graph.readout().revision).ok, true);
  assert.equal(h.graph.survey().ok, true);
  // Fixture-installed modules isolate terminal accounting from the already-tested
  // physical contribution path; they are not newly granted material or receipts.
  h.graph._row.installedModuleIds = ['power', 'guide', 'cargo'];
  const ilex = freshIlexArk(); ilex.phase = 'settled';
  for (const id of ILEX_VAULT_IDS) ilex.vaults[id].status = 'lost';
  ilex.vaults.vault_1.status = 'delivered';
  ilex.settlement = { id: `${ILEX_ARK.id}:outcome`, stationId: ILEX_ARK.stationId,
    deliveredVaultIds: ['vault_1'], at: 1, harvestAt: 1 + ILEX_ARK.harvestDelayS,
    rewardCr: ILEX_ARK.baseRewardCr + ILEX_ARK.vaultRewardCr };
  h.state.ilexArk = ilex;
  const last = freshLastShiftRecord(); last.knownClueIds = LAST_SHIFT_CLUES.map(c => c.id);
  last.receipts = [{ id: `${LAST_SHIFT.siteId}:archive:r1`, revision: 1, at: 1,
    clueIds: [...last.knownClueIds], destroyedClueIds: [], text: lastShiftReport(last.knownClueIds) }];
  h.state.world.lastShift = last;
  assert.equal(h.graph.evidence().cargoVariant, 'seed');
  assert.equal(h.graph.evidence().account, 'supported');
  const tick = () => { h.state.tick++; h.state.simTime++; h.graph.update(); };
  tick(); assert.equal(h.state.player.credits, 80);
  assert.equal(h.graph.dispatch().ok, true);
  const entry = h.helpers.npcJobs.get(MILE_CONVOY_JOB), hull = h.state.entities.get(entry.entityId);
  const arrive = (witnessed = false) => {
    native.set(hull, { ...MILE_CONVOY_ROUTE[0] }); traffic.canAdvanceJob(entry, hull);
    native.set(hull, { x: POS.x, z: POS.z - 100 }); traffic.canAdvanceJob(entry, hull);
    native.set(hull, { ...MILE_CONVOY_ROUTE[1] }); entry.job.phase = 'complete';
    if (!witnessed) { player.pos = { x: POS.x + 1000, z: POS.z }; native.set(player, { ...player.pos }); }
    assert.equal(traffic.finishJob(entry, hull), true);
    assert.equal(traffic.readConvoy(MILE_CONVOY_JOB).witnessedByPlayer, witnessed);
  };
  const inspect = () => h.bus.emit('scan:completed', { targetId: site.id });
  const close = () => { integration.dispose(); prompt.destroy(); deck.destroy(); h.dispose(); };
  return { ...h, traffic, native, player, doc, deck, tick, arrive, inspect, close };
}

test('terminal unwitnessed arrival is honest PARTIAL through prompt and owner Continue', () => {
  const h = boot();
  try {
    h.arrive(false); h.tick();
    assert.equal(h.graph.readout().finalConvoyOutcome, 'arrived');
    assert.equal(h.graph.readout().branch, 'PARTIAL', 'all modules and full evidence do not invent a witnessed finale');
    assert.equal(h.graph.prepareMilestone('witness_convoy'), null);
    assert.equal(h.state.player.credits, 80);
    h.player.pos = { ...POS }; h.native.set(h.player, { ...POS }); h.tick(); h.inspect();
    assert(h.doc.body.textContent.includes('Convoy: arrived.'));
    assert(h.doc.body.textContent.includes('Witness milestone not yet recorded. No witness reward paid.'));
    assert(!h.doc.body.textContent.includes('First convoy in progress'));
    assert(!h.doc.body.textContent.includes('REQUEST THE FIRST CONVOY'));
    assert.equal(h.graph.dispatch().reason, 'final-convoy-already-dispatched');
    // Drop the synthetic module-only setup before testing a schema-valid owner
    // save. Arrival/witness truth does not depend on inventing material receipts.
    h.graph._row.installedModuleIds = [];
    const graph = h.graph.serialize(), traffic = h.traffic.serialize(), economy = h.e.serialize();
    assert.equal(validHundredHandSaveSection('hundredHandMileTraffic', traffic), true);
    assert.equal(validHundredHandSaveSection('hundredHandMile', graph), true);
    h.bus.emit('save:restoring'); h.graph.deserialize(graph); h.traffic.deserialize(traffic); h.bus.emit('save:loaded');
    h.tick(); h.tick(); h.inspect();
    assert.equal(h.graph.readout().finalConvoyOutcome, 'arrived');
    assert.equal(h.graph.readout().branch, 'PARTIAL');
    assert.equal(h.traffic.readConvoy(MILE_CONVOY_JOB).witnessedByPlayer, false);
    assert.equal(h.graph.prepareMilestone('witness_convoy'), null);
    assert.equal(h.graph.dispatch().reason, 'final-convoy-already-dispatched');
    assert.equal(h.state.player.credits, 80);
    assert.deepEqual(h.e.serialize().committedIntents, economy.committedIntents);
    assert(!h.doc.body.textContent.includes('First convoy in progress'));
  } finally { h.close(); }
});

test('genuine witness deferred while away still settles once on return after Continue', () => {
  const h = boot();
  try {
    h.arrive(true);
    h.player.pos = { x: POS.x + 1000, z: POS.z }; h.native.set(h.player, { ...h.player.pos });
    h.tick(); assert.equal(h.graph.readout().finalConvoyOutcome, 'arrived');
    assert.equal(h.graph.prepareMilestone('witness_convoy'), null);
    h.graph._row.installedModuleIds = [];
    const graph = h.graph.serialize(), traffic = h.traffic.serialize();
    assert.equal(validHundredHandSaveSection('hundredHandMile', graph), true);
    let witnessEvents = 0;
    h.bus.on('hundredHandMile:milestone', event => {
      if (event.chapterId !== 'witness_convoy') return;
      witnessEvents++;
      assert.equal(h.graph.serialize().finalConvoyOutcome, 'arrived');
      assert(h.graph.prepareMilestone('witness_convoy'));
      h.graph.update(); // synchronous listeners cannot duplicate completion
    });
    h.bus.emit('save:restoring'); h.graph.deserialize(graph); h.traffic.deserialize(traffic); h.bus.emit('save:loaded');
    h.player.pos = { ...POS }; h.native.set(h.player, { ...POS }); h.inspect();
    assert(h.doc.body.textContent.includes('Witness milestone not yet recorded. No witness reward paid.'));
    assert(!h.doc.body.textContent.includes('No crossing witness recorded'));
    assert.equal(h.traffic.readConvoy(MILE_CONVOY_JOB).witnessedByPlayer, true);
    assert.equal(h.state.player.credits, 80);
    h.tick(); h.tick(); h.inspect();
    assert(h.graph.readout().completedMilestoneIds.includes('witness_convoy'));
    assert.equal(h.state.player.credits, 260);
    assert(!h.doc.body.textContent.includes('Witness milestone not yet recorded'));
    const saved = h.graph.serialize(); h.graph.deserialize(saved); h.tick(); h.tick();
    assert.equal(h.state.player.credits, 260);
    assert.equal(witnessEvents, 1);
    assert.equal(h.graph.dispatch().reason, 'final-convoy-already-dispatched');
  } finally { h.close(); }
});

test('legacy pending graph reconciles saved unwitnessed arrival without retroactive credit', () => {
  const h = boot();
  try {
    h.arrive(false);
    h.graph._row.installedModuleIds = [];
    const graph = h.graph.serialize(), traffic = h.traffic.serialize();
    assert.equal(graph.finalConvoyOutcome, null);
    assert.equal(traffic.outcome, 'arrived');
    assert.equal(validHundredHandSaveSection('hundredHandMile', graph), true);
    assert.equal(validHundredHandSaveSection('hundredHandMileTraffic', traffic), true);
    h.bus.emit('save:restoring'); h.graph.deserialize(graph); h.traffic.deserialize(traffic); h.bus.emit('save:loaded');
    h.player.pos = { ...POS }; h.native.set(h.player, { ...POS }); h.tick(); h.tick(); h.inspect();
    assert.equal(h.graph.readout().finalConvoyOutcome, 'arrived');
    assert.equal(h.graph.readout().branch, 'PARTIAL');
    assert.equal(h.graph.prepareMilestone('witness_convoy'), null);
    assert.equal(h.state.player.credits, 80);
    assert.equal(h.graph.dispatch().reason, 'final-convoy-already-dispatched');
    assert(!h.doc.body.textContent.includes('First convoy in progress'));
  } finally { h.close(); }
});
